{"script":"// Find all the product links and their ratings/prices
const products = document.querySelectorAll('h2');
const result = [];
products.forEach(h2 => {
  const link = h2.closest('a');
  if (link) {
    // Get the parent product container
    const container = h2.closest('[data-component-type="s-search-result"]') || h2.closest('div.s-result-item');
    if (container) {
      const ratingEl = container.querySelector('[aria-label*="out of 5 stars"]');
      const priceEl = container.querySelector('.a-price .a-offscreen');
      result.push({
        title: h2.textContent.trim().substring(0, 80),
        rating: ratingEl?.getAttribute('aria-label')?.substring(0, 50),
        price: priceEl?.textContent?.trim(),
        href: link.getAttribute('href')?.substring(0, 100)
      });
    }
  }
});
return result;"}

