{"script":"// Find the Color section and its options
const headers = document.querySelectorAll('div');
const colorSection = [];
for (const h of headers) {
  if (h.textContent.trim() === 'Color' && h.children.length === 0) {
    let parent = h.parentElement;
    // Find the parent that contains the color filter list
    for (let i = 0; i < 3; i++) {
      const links = parent.querySelectorAll('a[aria-label*="filter"]');
      if (links.length > 0) {
        links.forEach(l => colorSection.push({label: l.getAttribute('aria-label'), href: l.getAttribute('href')}));
        break;
      }
      parent = parent.parentElement;
    }
    break;
  }
}
return colorSection;"}

